import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: rate limiting (basic)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = requestCounts.get(ip) || 0;
  if (count > 1000) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  next();
});
setInterval(() => requestCounts.clear(), 60000);

// Auth middleware
function authenticate(req, res, next) {
  const token = req.headers['authorization']?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  // Token validation via HMAC - tokens are userId:timestamp:hmac
  const parts = token.split(':');
  if (parts.length !== 3) return res.status(401).json({ error: 'invalid token' });
  const [userId, timestamp, hmac] = parts;
  const expected = crypto.createHmac('sha256', process.env.TOKEN_SECRET || 'dev-secret')
    .update(`${userId}:${timestamp}`).digest('hex');
  if (hmac !== expected) return res.status(401).json({ error: 'invalid token' });
  if (Date.now() - parseInt(timestamp) > 3600000) return res.status(401).json({ error: 'expired' });
  req.userId = userId;
  next();
}

// Search endpoint with filtering
