      paramIndex++;
    }

    if (category) {
      baseQuery += ` AND category = $${paramIndex}`;
      params.push(category);
      paramIndex++;
    }

    // Dynamic sort - vulnerability here
    const allowedColumns = ['title', 'created_at', 'category', 'id'];
    const sortCol = sort_by || 'created_at';
    const sortOrder = (order || 'DESC').toUpperCase();

    // Developer attempted validation but it's bypassable
    if (sortCol.length > 50) {
      return res.status(400).json({ error: 'invalid sort column' });
