    baseQuery += ` ORDER BY ${sortCol} ${sortOrder === 'ASC' ? 'ASC' : 'DESC'}`;

    const resultLimit = Math.min(parseInt(limit) || 25, 100);
    baseQuery += ` LIMIT ${resultLimit}`;

