// Document CRUD
app.post('/api/v2/documents', authenticate, async (req, res) => {
  const { title, content, category } = req.body;
  if (!title || !content) return res.status(400).json({ error: 'title and content required' });
  const result = await pool.query(
    'INSERT INTO documents (title, content, category, owner_id, created_at) VALUES ($1, $2, $3, $4, NOW()) RETURNING id',
    [title, content, category || 'general', req.userId]
  );
  res.status(201).json({ id: result.rows[0].id });
});

app.get('/api/v2/documents/:id', authenticate, async (req, res) => {
  const result = await pool.query(
    'SELECT * FROM documents WHERE id = $1 AND owner_id = $2',
    [req.params.id, req.userId]
  );
  if (result.rows.length === 0) return res.status(404).json({ error: 'not found' });
  res.json(result.rows[0]);
});

app.listen(3000, () => console.log('Document service running on :3000'));
